nodes = []
for r in roots:
    collect(r[1] if r[0] == 'root' else r[2], nodes)
for r in roots:
    assign_stages(r[1] if r[0] == 'root' else r[2], 11, rng)
# bulk / direct split and spans
for n in nodes:
    n.span = 2 if n.type in (2, 3, 5) else 1
    n.direct = []
    n.bulk_keys = []
    if n.type == 3:
        keys = [k for (k, _) in n.children]
        if direct_children:
            k = rng.randint(0, min(3, len(keys) - 4))
            n.direct = sorted(rng.sample(keys, k))
        n.bulk_keys = [k for k in keys if k not in n.direct]
        for (k, c) in n.children:
            if k in n.bulk_keys:
                c.bulk_root = True
                c.span = 2
